style.css:
/* Page background + extra‑soft pastel text */
body {
    background-color: #ffffff;     /* plain white background */
    color: #b7e4ff;                /* softer pastel blue text */
    font-family: Arial, sans-serif;
}

/* Ultra‑soft pastel blue buttons */
button,
input[type="button"],
input[type="submit"],
input[type="reset"] {
    background-color: #e8f6ff;     /* ultra‑soft pastel blue */
    color: #b7e4ff;                /* matching pastel text */
    border: none;
    padding: 10px 18px;
    border-radius: 6px;
    font-size: 16px;
    cursor: pointer;
    transition: background-color 0.25s ease;
}

/* Hover effect — still soft, just a touch lighter */
button:hover,
input[type="button"]:hover,
input[type="submit"]:hover,
input[type="reset"]:hover {
    background-color: #d6efff;     /* slightly lighter pastel */
}
